class PDFObjRef(PDFObject):
    def __init__(self, doc: Optional["PDFDocument"], objid: int, _: object) -> None:
        if objid == 0:
            if settings.STRICT:
                raise PDFValueError("PDF object id cannot be 0.")
        self.doc = doc
        self.objid = objid

    def resolve(self, default: object = None) -> Any:
        """Resolves the reference by retrieving the object from the document."""
        if self.doc is None:
            if settings.STRICT:
                raise PDFValueError("PDFObjRef.doc is null")
            return default
        try:
            return self.doc.getobj(self.objid)
        except PDFObjectNotFound:
            if settings.STRICT:
                raise
            return default

